/**
 * quest rollback <feature-id> [--regressor <feature-id>]
 *
 * Reverts the implementation commit for a feature and marks it as passes:false.
 * If --regressor is provided, marks that feature as passes:false too so both
 * are re-queued for re-implementation.
 */
program
  .command('rollback <feature-id>')
  .description('Revert a feature\'s implementation commit and re-queue it for re-implementation')
  .option('--regressor <feature-id>', 'Feature ID that caused the regression (also re-queued)')
  .option('-d, --project-dir <dir>', 'Project directory (default: cwd)')
  .action(async (featureId: string, opts: { regressor?: string; projectDir?: string }) => {
    const projectDir = resolve(opts.projectDir ?? process.cwd())
    const orch = new Orchestrator({ projectDir })
    try {
      await orch.rollbackFeature(featureId, opts.regressor)
      console.log(chalk.green(`✓ Rollback complete. Run 'quest run' to re-implement.`))
    } catch (err) {
      console.error(chalk.red(`✗ Rollback failed: ${err instanceof Error ? err.message : err}`))
      process.exit(1)
    }
  })

program.parse()

